#include "all_fractal_definitions.h"

class cFractalInvPlaneReflection : public cAbstractFractal
{
public:
	cFractalInvPlaneReflection();
	void FormulaCode(CVector4 &z, const sFractal *fractal, sExtendedAux &aux) override;
};

cFractalInvPlaneReflection::cFractalInvPlaneReflection() : cAbstractFractal()
{
	nameInComboBox = "T>Inv Plane Reflection";
	internalName = "inv_plane_reflection";
	internalID = fractal::inv_plane_reflection;
	DEType = analyticDEType;
	DEFunctionType = linearDEFunction;
	cpixelAddition = cpixelDisabledByDefault;
	defaultBailout = 100.0;
	DEAnalyticFunction = analyticFunctionLinear;
	coloringFunction = coloringFunctionDefault;
}

void cFractalInvPlaneReflection::FormulaCode(
	CVector4 &z, const sFractal *fractal, sExtendedAux &aux)
{
	// Plane reflection
	CVector3 normal = CVector3(0, 0, 1);
	normal.Normalize();
	
	CVector3 planePoint = CVector3(0, 0, 0);
	
	// Distance to plane
	double dist = (z - planePoint).Dot(normal);
	
	// Reflect across plane
	z = z - normal * (2.0 * dist);
}
